package com.aidevos.orchestrator.qualitygate;
import com.aidevos.orchestrator.validation.security.SecuritySeverity; import org.springframework.boot.context.properties.ConfigurationProperties; import org.springframework.stereotype.Component;
@Component @ConfigurationProperties(prefix="aidevos.quality-gate")
public class QualityGatePolicy { private String policyVersion="v1"; private QualityGateDecision secret=QualityGateDecision.BLOCK,critical=QualityGateDecision.BLOCK,high=QualityGateDecision.REQUIRE_APPROVAL,medium=QualityGateDecision.PASS,low=QualityGateDecision.PASS,requiredProviderUnavailable=QualityGateDecision.REQUIRE_APPROVAL; public QualityGateDecision forSeverity(SecuritySeverity s){return switch(s){case CRITICAL->critical;case HIGH->high;case MEDIUM->medium;case LOW,INFO->low;};} public String getPolicyVersion(){return policyVersion;} public void setPolicyVersion(String v){policyVersion=v;} public QualityGateDecision getSecret(){return secret;} public void setSecret(QualityGateDecision v){secret=v;} public QualityGateDecision getCritical(){return critical;} public void setCritical(QualityGateDecision v){critical=v;} public QualityGateDecision getHigh(){return high;} public void setHigh(QualityGateDecision v){high=v;} public QualityGateDecision getMedium(){return medium;} public void setMedium(QualityGateDecision v){medium=v;} public QualityGateDecision getLow(){return low;} public void setLow(QualityGateDecision v){low=v;} public QualityGateDecision getRequiredProviderUnavailable(){return requiredProviderUnavailable;} public void setRequiredProviderUnavailable(QualityGateDecision v){requiredProviderUnavailable=v;} }
